From b4523f9ce6a67f942715b1f24dc75e875e028884 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 00:45:15 +0100
Subject: [PATCH] KDialogJobUiDelegate: don't block the application without a
 parent window

A job error without a parent window was shown with a blocking message
box, which is modal for the whole application and froze all of Plasma
until it was closed. Show it as a non-modal dialog in that case instead.

BUG: 526959
---
 src/kdialogjobuidelegate.cpp | 15 +++++++++++++++
 1 file changed, 15 insertions(+)

diff --git a/src/kdialogjobuidelegate.cpp b/src/kdialogjobuidelegate.cpp
index 8698258..d935451 100644
--- a/src/kdialogjobuidelegate.cpp
+++ b/src/kdialogjobuidelegate.cpp
@@ -9,6 +9,7 @@

 #include "kdialogjobuidelegate.h"

+#include <QIcon>
 #include <QPointer>
 #include <QQueue>
 #include <QWidget>
@@ -16,6 +17,7 @@
 #include <KJob>
 #include <KJobWidgets>
 #include <KMessageBox>
+#include <KMessageDialog>

 #include <config-kjobwidgets.h>
 #if WITH_X11
@@ -69,6 +71,19 @@ void KDialogJobUiDelegatePrivate::next()

     QSharedPointer<MessageBoxData> data = queue.dequeue();

+    // Without a parent window a blocking message box is modal for the whole application,
+    // which freezes e.g. all of Plasma, so show it without blocking and go on when it is closed
+    if (!data->widget) {
+        auto *dialog = new KMessageDialog(data->type == ErrorDialog ? KMessageDialog::Error : KMessageDialog::Information, data->msg);
+        dialog->setAttribute(Qt::WA_DeleteOnClose);
+        dialog->setCaption(QString());
+        dialog->setIcon(QIcon());
+        dialog->setButtons();
+        connect(dialog, &QDialog::finished, this, &KDialogJobUiDelegatePrivate::next);
+        dialog->show();
+        return;
+    }
+
     // kmessagebox starts a new event loop which can cause this to get deleted
     // https://bugs.kde.org/show_bug.cgi?id=356321#c16
     QPointer<KDialogJobUiDelegatePrivate> thisGuard(this);
